package com.acttub.actingapi.auth;
import static org.assertj.core.api.Assertions.*; import java.time.*; import java.util.*; import java.util.concurrent.*; import com.acttub.actingapi.support.PostgresContainerSupport; import org.junit.jupiter.api.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.test.context.*; import org.springframework.test.web.servlet.*; import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
@SpringBootTest(properties="JWT_SECRET=회전-비ASCII-secret") @AutoConfigureMockMvc
class RefreshRotationIT {@DynamicPropertySource static void db(DynamicPropertyRegistry r){String name=PostgresContainerSupport.createDatabaseName("refresh_rotation");r.add("spring.datasource.url",()->PostgresContainerSupport.jdbcUrlFor(name));r.add("spring.datasource.username",PostgresContainerSupport.POSTGRES::getUsername);r.add("spring.datasource.password",PostgresContainerSupport.POSTGRES::getPassword);}
    @Autowired JdbcTemplate jdbc;@Autowired JwtService jwt;@Autowired AuthStore store;@Autowired MockMvc mvc;
    @Test void simultaneousReuseReturnsOneSuccessOneUnauthorizedAndRevokesAll()throws Exception{UUID user=UUID.randomUUID();jdbc.update("INSERT INTO users(id,status) VALUES (?,'active'::user_status_t)",user);var old=jwt.issueRefreshToken(user);store.issueRefresh(user,JwtService.hashToken(old.value()),old.expiresAt(),null,Instant.now());String json="{\"refresh_token\":\""+old.value()+"\"}";ExecutorService pool=Executors.newFixedThreadPool(2);try{CountDownLatch start=new CountDownLatch(1);Callable<Integer> call=()->{start.await();return mvc.perform(post("/v2/auth/refresh").contentType("application/json").content(json)).andReturn().getResponse().getStatus();};Future<Integer>a=pool.submit(call),b=pool.submit(call);start.countDown();assertThat(List.of(a.get(),b.get())).containsExactlyInAnyOrder(200,401);}finally{pool.shutdownNow();}assertThat(jdbc.queryForObject("SELECT count(*) FROM refresh_tokens WHERE user_id=? AND revoked_at IS NULL",Integer.class,user)).isZero();assertThat(jdbc.queryForObject("SELECT bool_and(token_hash ~ '^[0-9a-f]{64}$') FROM refresh_tokens WHERE user_id=?",Boolean.class,user)).isTrue();}
}
